func runForkReceiverOwnershipJourney(t *testing.T, backend servedparity.Backend, receivers []canonicalrouting.ForkReceiver, entitylessProducer bool, options ...forkReceiverJourneyOptions) {
	t.Helper()
	var option forkReceiverJourneyOptions
	if len(options) != 0 {
		option = options[0]
	}
	var selected *selectedStoreOwner
	previous := projectRuntimePersistenceForServe
	projectRuntimePersistenceForServe = func(owner *selectedStoreOwner) serveRuntimePersistence {
		selected = owner
		return previous(owner)
	}
	t.Cleanup(func() {
		projectRuntimePersistenceForServe = previous
	})
	root := canonicalrouting.CopyForkReceiverOwnership(t, receivers, entitylessProducer)
	if option.repeated {
		root = canonicalrouting.CopyForkReceiverRepeatedOwnership(t, receivers)
	}
	prefix, seedName, requestName := "", "start.seeded", "start.requested"
	if option.nested {
		root = canonicalrouting.CopyForkReceiverNestedOwnership(t, receivers)
		prefix, seedName, requestName = "branch/", "outer.seeded", "outer.requested"
	}
	if option.executionOnly {
		root = canonicalrouting.CopyForkReceiverExecutionOwnership(t, receivers, entitylessProducer, option.nested, option.repeated)
	}
	requireEffect := requireForkReceiverEffect
	if option.executionOnly {
		requireEffect = func(t *testing.T, rt servedControlProofRuntime, runID, eventID, path, label, kind, entityID string) events.DeliveryRoute {
			for _, receiver := range receivers {
				if prefix+receiver.Path == path {
					return requireForkReceiverExecution(t, rt, runID, eventID, path, label, kind, entityID, receiver.Policy)
				}
			}
			t.Fatalf("undeclared receiver %s", path)
			return events.DeliveryRoute{}
		}
	}
	rt := startServedTestSetupEntitiesProofRuntimeFromSource(t, backend, root)
	seed := requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"event_name": seedName, "bundle_hash": rt.BundleHash, "payload": map[string]any{"token": "receiver-proof"}, "idempotency_key": "ownership-seed"})
	waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, seed.RunID)
	waitForkReceiverSourceCompletion(t, rt.ReceiverStateReader, seed.RunID)
	seedRows := readWorkspaceProofReceiverRows(t, rt.Runtime.Bus.Store(), seed.RunID)
	seedCompanions := map[string]map[string][]string{}
	for _, receiver := range receivers {
		if receiver.Policy == canonicalrouting.ForkReceiverOptionalAbsent || receiver.Policy == canonicalrouting.ForkReceiverOptionalExisting {
			path := prefix + receiver.Path
			seedCompanions[path] = readForkReceiverCompanions(t, rt.ReceiverStateReader, seed.RunID, path)
		}
	}
	request := map[string]any{"event_name": requestName, "run_id": seed.RunID, "source_event_id": seed.EventID, "payload": map[string]any{"token": "receiver-proof"}, "idempotency_key": "ownership-request"}
	started := requireServedEventPublishRPCResult(t, rt.Endpoint, request)
	waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, seed.RunID)
	waitForkReceiverSourceCompletion(t, rt.ReceiverStateReader, seed.RunID)
	if started.RunID != seed.RunID {
		t.Fatal("second source ingress escaped the seeded run")
	}
	var frontier string
	if err := rt.DB.QueryRow(`SELECT event_id FROM events WHERE run_id=$1 AND event_name=$2`, seed.RunID, prefix+"producer/work.ready").Scan(&frontier); err != nil {
		t.Fatalf("actual producer did not emit fork frontier: %v", err)
	}
	frontiers := []string{frontier}
	if option.repeated {
		request["idempotency_key"] = "ownership-request-second"
		second := requireServedEventPublishRPCResult(t, rt.Endpoint, request)
		if second.EventID == started.EventID || second.RunID != seed.RunID {
			t.Fatal("distinct source occurrence collapsed")
		}
		waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, seed.RunID)
		waitForkReceiverSourceCompletion(t, rt.ReceiverStateReader, seed.RunID)
		if err := rt.DB.QueryRow(`SELECT event_id FROM events WHERE run_id=$1 AND event_name=$2 AND event_id<>$3`, seed.RunID, prefix+"producer/work.ready", frontier).Scan(&frontier); err != nil {
			t.Fatal(err)
		}
		frontiers = append(frontiers, frontier)
		beforeDuplicate := readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), seed.RunID)
		beforeDuplicateNotices := readForkReceiverNoticeDomain(t, rt, seed.RunID)
		duplicate := requireServedEventPublishRPCResult(t, rt.Endpoint, request)
		if !reflect.DeepEqual(second, duplicate) || !reflect.DeepEqual(beforeDuplicate, readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), seed.RunID)) || !reflect.DeepEqual(beforeDuplicateNotices, readForkReceiverNoticeDomain(t, rt, seed.RunID)) {
			t.Fatal("duplicate ingress rematerialized a source occurrence")
		}
	}
	sourceRows := readWorkspaceProofReceiverRows(t, rt.Runtime.Bus.Store(), seed.RunID)
	if option.executionOnly {
		for _, receiver := range receivers {
			if receiver.Policy == canonicalrouting.ForkReceiverOptionalAbsent || receiver.Policy == canonicalrouting.ForkReceiverOptionalExisting {
				path := prefix + receiver.Path
				if !reflect.DeepEqual(seedRows[path], sourceRows[path]) {
					t.Fatalf("optional receiver changed seeded state %s: before=%+v after=%+v", path, seedRows[path], sourceRows[path])
				}
				requireOptionalForkReceiverHeaderProgress(t, rt, seed.RunID, path, seedCompanions[path], readForkReceiverCompanions(t, rt.ReceiverStateReader, seed.RunID, path), len(frontiers))
			}
		}
	}
	producerEvidence := readForkReceiverProducerEvidence(t, rt.Runtime.Bus.Store(), seed.RunID, frontier)
	producer, producerExists := sourceRows[prefix+"producer"]
	if producerExists == entitylessProducer || (producerExists && (producer.Type != "work" || producer.Fields["marker"] != "producer-owned")) {
		t.Fatalf("source producer prerequisite: %+v", sourceRows)
	}
	producerRoute := producerEvidence.Source.Route()
	var producerHeaderID string
	if err := rt.DB.QueryRow(`SELECT entity_id FROM flow_instances WHERE run_id=$1 AND instance_path=$2 AND flow_template=$2`, seed.RunID, prefix+"producer").Scan(&producerHeaderID); err != nil {
		t.Fatal(err)
	}
	if (producerExists && producer.ID != producerHeaderID) || producerEvidence.Source.Kind() != events.RoutingSourceStaticFlow || producerRoute.FlowID != prefix+"producer" || producerRoute.FlowInstance != prefix+"producer" || producerRoute.EntityID != producerHeaderID {
		t.Fatalf("source event lacks independently expected producer ownership: %+v rows=%+v", producerEvidence, sourceRows)
	}
	sourceRoutes := map[string]events.DeliveryRoute{}
	for _, receiver := range receivers {
		path := prefix + receiver.Path
		kind, id := "existing_entity", ""
		if receiver.Policy != canonicalrouting.ForkReceiverOptionalAbsent {
			row, exists := sourceRows[path]
			marker := receiver.Path + "-owned"
			kind = "existing_entity"
			if receiver.Policy == canonicalrouting.ForkReceiverConstructorOwned {
				marker = receiver.Path + "-created"
			}
			if !exists || row.ID == producer.ID || row.Type != "receipt" || row.State != "active" || row.Fields["marker"] != marker {
				t.Fatalf("independent source receiver prerequisite: %s %+v", receiver.Path, sourceRows)
			}
			id = row.ID
		} else {
			row, exists := sourceRows[path]
			if !exists || row.Type != "receipt" || len(row.Fields) != 0 {
				t.Fatalf("optional empty contract lacks its exact initialized field companion: %+v", sourceRows)
			}
			id = row.ID
		}
		for _, occurrence := range frontiers {
			sourceRoutes[path] = requireEffect(t, rt, seed.RunID, occurrence, path, receiver.Path, kind, id)
		}
	}
	if option.repeated {
		family, ok := selected.RunFork()
		if !ok {
			t.Fatal("missing source planner")
		}
		plan, err := family.Plan(servedControlProofAuthorActivityContext(t, rt), runfork.RunForkPlanRequest{SourceRunID: seed.RunID, At: frontier})
		if err != nil {
			t.Fatal(err)
		}
		for _, occurrence := range frontiers {
			if got := readForkReceiverProducerEvidence(t, rt.Runtime.Bus.Store(), seed.RunID, occurrence); got != producerEvidence {
				t.Fatalf("same-owner occurrence lost producer or execution mode: first=%+v got=%+v", producerEvidence, got)
			}
			for _, receiver := range receivers {
				matches := 0
				for _, item := range plan.PendingWork {
					node, isNode := item.DeliveryRoute.Recipient.Node()
					if item.EventID == occurrence && isNode && node.FlowPath() == receiver.Path && node.NodeID() == "collector" {
						matches++
						if !reflect.DeepEqual(item.DeliveryRoute.Normalized(), sourceRoutes[receiver.Path]) {
							t.Fatalf("fixed snapshot collapsed same-owner delivery evidence: %+v", item)
						}
					}
				}
				if matches != 1 {
					t.Fatalf("fixed snapshot event=%s receiver=%s associations=%d, want one", occurrence, receiver.Path, matches)
				}
			}
		}
	}
	if option.executionOnly {
		for _, occurrence := range frontiers {
			requireForkReceiverMutationOwners(t, rt, seed.RunID, occurrence, prefix, receivers)
		}
	}
	t.Logf("source success reached: run=%s frontier=%s receivers=%d", seed.RunID, frontier, len(receivers))
	if option.nested {
		siblingSeed := requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"event_name": seedName, "bundle_hash": rt.BundleHash, "payload": map[string]any{"token": "receiver-proof"}, "idempotency_key": "ownership-sibling-seed"})
		waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, siblingSeed.RunID)
		waitForkReceiverSourceCompletion(t, rt.ReceiverStateReader, siblingSeed.RunID)
		requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"event_name": requestName, "run_id": siblingSeed.RunID, "source_event_id": siblingSeed.EventID, "payload": map[string]any{"token": "receiver-proof"}, "idempotency_key": "ownership-sibling-request"})
		waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, siblingSeed.RunID)
		waitForkReceiverSourceCompletion(t, rt.ReceiverStateReader, siblingSeed.RunID)
		if siblingSeed.RunID == seed.RunID {
			t.Fatal("independent sibling run collapsed")
		}
		var siblingFrontier string
		if err := rt.DB.QueryRow(`SELECT event_id FROM events WHERE run_id=$1 AND event_name=$2`, siblingSeed.RunID, prefix+"producer/work.ready").Scan(&siblingFrontier); err != nil {
			t.Fatal(err)
		}
		siblingRows := readWorkspaceProofReceiverRows(t, rt.Runtime.Bus.Store(), siblingSeed.RunID)
		for _, receiver := range receivers {
			path := prefix + receiver.Path
			if siblingRows[path].ID != sourceRows[path].ID || siblingRows[path].Flow != path {
				t.Fatalf("sibling fixture did not exercise same entity ID in separate run: source=%+v sibling=%+v", sourceRows[path], siblingRows[path])
			}
			requireEffect(t, rt, siblingSeed.RunID, siblingFrontier, path, receiver.Path, "existing_entity", siblingRows[path].ID)
		}
		siblingDomain, siblingCompanions := readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), siblingSeed.RunID), readForkReceiverCompanions(t, rt.ReceiverStateReader, siblingSeed.RunID)
		siblingNotices := readForkReceiverNoticeDomain(t, rt, siblingSeed.RunID)
		defer func() {
			if !reflect.DeepEqual(siblingDomain, readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), siblingSeed.RunID)) || !reflect.DeepEqual(siblingCompanions, readForkReceiverCompanions(t, rt.ReceiverStateReader, siblingSeed.RunID)) || !reflect.DeepEqual(siblingNotices, readForkReceiverNoticeDomain(t, rt, siblingSeed.RunID)) {
				t.Error("fork mutated the independently executed sibling run")
			}
		}()
	}
	before := readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), seed.RunID)
	beforeCompanions := readForkReceiverCompanions(t, rt.ReceiverStateReader, seed.RunID)
	beforeNotices := readForkReceiverNoticeDomain(t, rt, seed.RunID)
	defer func() {
		if after := readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), seed.RunID); !reflect.DeepEqual(before, after) {
			t.Errorf("fork mutated source domain: before=%v after=%v", before, after)
		}
		if after := readForkReceiverCompanions(t, rt.ReceiverStateReader, seed.RunID); !reflect.DeepEqual(beforeCompanions, after) {
			t.Errorf("fork mutated source companion/readiness rows: before=%v after=%v", beforeCompanions, after)
		}
		if !reflect.DeepEqual(beforeNotices, readForkReceiverNoticeDomain(t, rt, seed.RunID)) {
			t.Error("fork changed source business notices")
		}
	}()
	params := map[string]any{"source_run_id": seed.RunID, "fork_event_id": frontier, "allow_source_freeze": true, "idempotency_key": "ownership-fork"}
	if option.afterSource != nil {
		option.afterSource(t, rt, selected, root, seed.RunID, frontier, receivers)
		return
	}
	if option.selectedMissing {
		const missingReceiver = "missing"
		selectedRoot := canonicalrouting.CopyForkReceiverOwnership(t, []canonicalrouting.ForkReceiver{{Path: "consumer", Policy: canonicalrouting.ForkReceiverOptionalAbsent}, {Path: missingReceiver, Policy: canonicalrouting.ForkReceiverRequiredMissing}}, false)
		bundle := loadWorkflowValidationBundleAt(t, selectedRoot)
		if selected == nil {
			t.Fatal("missing selected store owner")
		}
		seedStandingRuntimeContextBundle(t, selected.SourceArtifactWriter(), bundle)
		selectedHash := servedEventPublishFixtureBundleHash(t, selectedRoot)
		family, ok := selected.RunFork()
		if !ok {
			t.Fatal("missing actual fork executor")
		}
		beforeRefusal := snapshotForkReceiverApplication(t, rt.ReadApplicationSnapshot)
		for attempt := 0; attempt < 2; attempt++ {
			result, err := family.Execute(servedControlProofAuthorActivityContext(t, rt), runforkexecution.SelectedContractExecutionRequest{SourceRunID: seed.RunID, At: frontier, AllowSourceFreeze: true, ExpectedBundleHash: selectedHash, SourceLoader: runforkexecution.SourceArtifactSelectedContractSourceLoader{RepoRoot: repoRootForTest(), PlatformSpecPath: filepath.Join(repoRootForTest(), defaultPlatformSpecPath), Store: selected.SourceArtifactStore()}, ContractSelection: runfork.RunForkContractSelection{Mode: runfork.RunForkContractSelectionModeBundleHash, BundleHash: selectedHash}, AgentRuntime: rt.ForkRuntime})
			if err == nil || !strings.Contains(err.Error(), "receiver target owner is missing") || !strings.Contains(err.Error(), missingReceiver) || result.ExecutedEventCount != 0 || result.Materialization.ForkRunID != "" {
				t.Fatalf("required missing receiver must reject before materialization: executions=%d child=%q err=%v", result.ExecutedEventCount, result.Materialization.ForkRunID, err)
			}
			if after := snapshotForkReceiverApplication(t, rt.ReadApplicationSnapshot); !reflect.DeepEqual(beforeRefusal, after) {
				t.Fatalf("required-missing attempt %d changed application state", attempt)
			}
		}
		return
	}
	var fork, replay apiv1.RunForkExecutionResult
	requireServedJSONRPCResult(t, rt.Endpoint, "run.fork", params, &fork)
	if fork.SourceRunID != seed.RunID || fork.ForkEventID != frontier || fork.ForkRunID == "" || fork.ForkRunID == seed.RunID || fork.ExecutedEventCount != 1 {
		t.Fatalf("fork identity: %+v", fork)
	}
	waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, fork.ForkRunID)
	childRows := readWorkspaceProofReceiverRows(t, rt.Runtime.Bus.Store(), fork.ForkRunID)
	childEvent := activityidentity.ForkLineageEventID(fork.ForkRunID, frontier)
	childProducer := readForkReceiverProducerEvidence(t, rt.Runtime.Bus.Store(), fork.ForkRunID, childEvent)
	if childProducer != producerEvidence {
		t.Fatalf("backend/container composition changed immutable non-root producer: source=%+v child=%+v", producerEvidence, childProducer)
	}
	if producerRoute.EntityID != "" {
		var childHeaderID string
		if err := rt.DB.QueryRow(`SELECT entity_id FROM flow_instances WHERE run_id=$1 AND instance_path=$2 AND flow_template=$3`, fork.ForkRunID, producerRoute.FlowInstance, producerRoute.FlowID).Scan(&childHeaderID); err != nil {
			t.Fatal(err)
		}
		row := childRows[producerRoute.FlowInstance]
		if childHeaderID != producerRoute.EntityID || (producerExists && (row.ID != producerRoute.EntityID || row.Type != producer.Type || row.Flow != producer.Flow)) {
			t.Fatalf("child producer route has no exact physical owner: route=%+v row=%+v", producerRoute, row)
		}
	}
	for _, receiver := range receivers {
		path := prefix + receiver.Path
		sourceRoute := sourceRoutes[path]
		id := sourceRoute.Target.Route().EntityID
		kind := sourceRoute.Target.Code()
		childRoute := requireEffect(t, rt, fork.ForkRunID, childEvent, path, receiver.Path, kind, id)
		if !reflect.DeepEqual(childRoute.ConnectClaim, sourceRoute.ConnectClaim) {
			t.Fatalf("fork changed exact compiled connect claim: source=%+v child=%+v", sourceRoute, childRoute)
		}
		if id == "" {
			t.Fatalf("constructed receiver lacks exact header identity: %s", path)
		}
		if got := childRows[path]; !reflect.DeepEqual(got, sourceRows[path]) {
			t.Fatalf("receiver state transferred or changed: source=%+v child=%+v", sourceRows[path], got)
		}
	}
	if producerExists && !reflect.DeepEqual(childRows[prefix+"producer"], producer) {
		t.Fatalf("producer state was rehomed: source=%+v child=%+v", producer, childRows)
	}
	if option.executionOnly {
		requireForkReceiverMutationOwners(t, rt, fork.ForkRunID, childEvent, prefix, receivers)
	}
	if entitylessProducer {
		if _, exists := childRows[prefix+"producer"]; exists {
			t.Fatalf("entityless producer acquired state: %+v", childRows)
		}
	}
	rootRow := childRows[fork.ForkRunID]
	if rootRow.ID != fork.ForkRunID || rootRow.Type != "root" || rootRow.Fields["marker"] != "root-owned" || rootRow.State != "active" {
		t.Fatalf("root remap/restoration: %+v", childRows)
	}
	childBefore := readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), fork.ForkRunID)
	childNotices, childCompanions := readForkReceiverNoticeDomain(t, rt, fork.ForkRunID), readForkReceiverCompanions(t, rt.ReceiverStateReader, fork.ForkRunID)
	requireServedJSONRPCResult(t, rt.Endpoint, "run.fork", params, &replay)
	if !reflect.DeepEqual(fork, replay) || !reflect.DeepEqual(childBefore, readServedForkRecipientSourceDomain(t, rt.Runtime.Bus.Store(), fork.ForkRunID)) || !reflect.DeepEqual(childNotices, readForkReceiverNoticeDomain(t, rt, fork.ForkRunID)) || !reflect.DeepEqual(childCompanions, readForkReceiverCompanions(t, rt.ReceiverStateReader, fork.ForkRunID)) {
		t.Fatal("same-key fork replay changed response, committed targets, or final effects")
	}
}

